package com.primehr.rsp.evaluation.api;
import com.primehr.rsp.evaluation.api.CommitteeDtos.*; import com.primehr.rsp.evaluation.application.*; import com.primehr.security.*; import com.primehr.shared.api.*; import jakarta.validation.*; import org.springframework.http.*; import org.springframework.security.core.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/primehr/v1/committees") public class CommitteeController {private final CommitteeService service;private final HrmpsbGovernancePermissionGuard permission;private final AgencyScopeResolver agency;public CommitteeController(CommitteeService s,HrmpsbGovernancePermissionGuard p,AgencyScopeResolver a){service=s;permission=p;agency=a;}@GetMapping public PageResponse<CommitteeResponse> list(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestParam(name="page",defaultValue="0")int page,@RequestParam(name="size",defaultValue="20")int size){permission.require(PrimeHrAction.ACCESS,t);return service.list(agency.resolveAgencyId(a),page,size);}@GetMapping("/{id}")public CommitteeResponse get(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@PathVariable String id){permission.require(PrimeHrAction.ACCESS,t);return service.get(agency.resolveAgencyId(a),id);}@PostMapping @ResponseStatus(HttpStatus.CREATED)public CommitteeResponse create(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@Valid @RequestBody SaveCommittee r){permission.require(PrimeHrAction.ADD,t);return service.create(agency.resolveAgencyId(a),r,t,c);}@PutMapping("/{id}")public CommitteeResponse update(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody SaveCommittee r){permission.require(PrimeHrAction.EDIT,t);return service.update(agency.resolveAgencyId(a),id,r,t,c);}@PostMapping("/{id}/publish")public CommitteeResponse publish(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Publish r){permission.require(PrimeHrAction.PUBLISH,t);return service.publish(agency.resolveAgencyId(a),id,r,t,c);}@PostMapping("/{id}/successors")@ResponseStatus(HttpStatus.CREATED)public CommitteeResponse successor(Authentication a,@RequestHeader(HttpHeaders.AUTHORIZATION)String t,@RequestHeader(value="X-Correlation-Id",required=false)String c,@PathVariable String id,@Valid @RequestBody Transition r){permission.require(PrimeHrAction.ADD,t);return service.successor(agency.resolveAgencyId(a),id,r,c);}}
